static int strip_comments(char *line, int in_quotes)
{
        int quote_count = in_quotes, backslash_count = 0;
        char *ptr;

        for (ptr = line; *ptr; ++ptr) {
                if (ptr[0] == '"' && ptr > line && ptr[-1] != '\\')
                        quote_count++;

                if ((ptr[0] == ';' || ptr[0] == '#') &&
                        (quote_count % 2) == 0 &&
                        (backslash_count % 2) == 0) {
                        ptr[0] = '\0';
                        break;
                }

                if (ptr[0] == '\\')
                        backslash_count++;
                else
                        backslash_count = 0;
        }

        /* skip any space at the end */
        while (ptr > line && git__isspace(ptr[-1])) {
                ptr--;
        }
        ptr[0] = '\0';

        return quote_count;
}


static int parse_section_header_ext(git_config_parser *reader, const char *line, const char *base_name, char **section_name)
{
        int c, rpos;
        char *first_quote, *last_quote;
        git_buf buf = GIT_BUF_INIT;
        size_t quoted_len, alloc_len, base_name_len = strlen(base_name);

        /*
         * base_name is what came before the space. We should be at the
         * first quotation mark, except for now, line isn't being kept in
         * sync so we only really use it to calculate the length.
         */

        first_quote = strchr(line, '"');
        if (first_quote == NULL) {
                set_parse_error(reader, 0, "Missing quotation marks in section header");
                goto end_error;
        }

        last_quote = strrchr(line, '"');
        quoted_len = last_quote - first_quote;

        if (quoted_len == 0) {
                set_parse_error(reader, 0, "Missing closing quotation mark in section header");
                goto end_error;
        }

        GITERR_CHECK_ALLOC_ADD(&alloc_len, base_name_len, quoted_len);
        GITERR_CHECK_ALLOC_ADD(&alloc_len, alloc_len, 2);

        if (git_buf_grow(&buf, alloc_len) < 0 ||
            git_buf_printf(&buf, "%s.", base_name) < 0)
                goto end_error;

        rpos = 0;

        line = first_quote;
        c = line[++rpos];

        /*
         * At the end of each iteration, whatever is stored in c will be
         * added to the string. In case of error, jump to out
         */
        do {

                switch (c) {
                case 0:
                        set_parse_error(reader, 0, "Unexpected end-of-line in section header");
                        goto end_error;

                case '"':
                        goto end_parse;

                case '\\':
                        c = line[++rpos];

                        if (c == 0) {
                                set_parse_error(reader, rpos, "Unexpected end-of-line in section header");
                                goto end_error;
                        }

                default:
                        break;
                }

                git_buf_putc(&buf, (char)c);
                c = line[++rpos];
        } while (line + rpos < last_quote);

end_parse:
        if (git_buf_oom(&buf))
                goto end_error;

        if (line[rpos] != '"' || line[rpos + 1] != ']') {
                set_parse_error(reader, rpos, "Unexpected text after closing quotes");
                git_buf_dispose(&buf);
                return -1;
        }

        *section_name = git_buf_detach(&buf);
        return 0;

end_error:
        git_buf_dispose(&buf);

        return -1;
}

static int parse_section_header(git_config_parser *reader, char **section_out)
{
        char *name, *name_end;
        int name_length, c, pos;
        int result;
        char *line;
        size_t line_len;

        git_parse_advance_ws(&reader->ctx);
        line = git__strndup(reader->ctx.line, reader->ctx.line_len);
        if (line == NULL)
                return -1;

        /* find the end of the variable's name */
        name_end = strrchr(line, ']');
        if (name_end == NULL) {
                git__free(line);
                set_parse_error(reader, 0, "Missing ']' in section header");
                return -1;
        }

        GITERR_CHECK_ALLOC_ADD(&line_len, (size_t)(name_end - line), 1);
        name = git__malloc(line_len);
        GITERR_CHECK_ALLOC(name);

        name_length = 0;
        pos = 0;

        /* Make sure we were given a section header */
        c = line[pos++];
        assert(c == '[');

        c = line[pos++];

        do {
                if (git__isspace(c)){
                        name[name_length] = '\0';
                        result = parse_section_header_ext(reader, line, name, section_out);
                        git__free(line);
                        git__free(name);
                        return result;
                }

                if (!config_keychar(c) && c != '.') {
                        set_parse_error(reader, pos, "Unexpected character in header");
                        goto fail_parse;
                }

                name[name_length++] = (char)git__tolower(c);

        } while ((c = line[pos++]) != ']');

        if (line[pos - 1] != ']') {
                set_parse_error(reader, pos, "Unexpected end of file");
                goto fail_parse;
        }

        git__free(line);

        name[name_length] = 0;
        *section_out = name;

        return 0;

fail_parse:
        git__free(line);
        git__free(name);
        return -1;
}

